for i in range(20):
    row = [0] * 23
    # Only set 9 at original frame positions
    if i < 6:
        row[0] = 9  # left frame
    if i >= 10 and i <= 16:
        row[22] = 9  # right frame
    # Fill with 1s where 6s were
    if i in list(range(6, 10)) + list(range(17, 20)):
        # Non-frame rows - fill entire row with 6 (or 1?)
        row[0] = 6
    # Default: all cells become 1 except edge 9s
    for j in range(23):
        if i < 6 and j == 0:
            row[j] = 9
        elif i >= 10 and i <= 16 and j == 22:
            row[j] = 9
